// removes // and /* */ comments; keeps string/char literals and C++ raw strings intact, keeps line breaks
function stripComments(src) {
  let out = '';
  let i = 0;
  const n = src.length;
  while (i < n) {
    const c = src[i], d = src[i + 1];
    if (c === '/' && d === '/') { while (i < n && src[i] !== '\n') i++; continue; }
    if (c === '/' && d === '*') {
      const e = src.indexOf('*/', i + 2);
      const end = e < 0 ? n : e + 2;
      out += src.slice(i, end).replace(/[^\n]/g, '');
      i = end; continue;
    }
    if (c === 'R' && d === '"' && (i === 0 || !/\w/.test(src[i - 1]))) {  // raw string R"delim( ... )delim"
      const p = src.indexOf('(', i + 2);
      const delim = src.slice(i + 2, p);
      const e = src.indexOf(')' + delim + '"', p);
      const end = e < 0 ? n : e + delim.length + 2;
      out += src.slice(i, end); i = end; continue;
    }
    if (c === '"' || c === "'") {
      let j = i + 1;
      while (j < n && src[j] !== c && src[j] !== '\n') j += (src[j] === '\\') ? 2 : 1;
      out += src.slice(i, j + 1); i = j + 1; continue;
    }
    out += c; i++;
  }
  return out;
}

// decodes one or more adjacent C string literals ("a" "b") into a JS string
function decodeCString(lits) {
  let s = '';
  const re = /"((?:[^"\\\n]|\\.)*)"/g;
  let m;
  while ((m = re.exec(lits))) {
    s += m[1].replace(/\\(x[0-9a-fA-F]{1,2}|[0-7]{1,3}|.)/g, (_, e) => {
      if (e[0] === 'x') return String.fromCharCode(parseInt(e.slice(1), 16));
      if (/^[0-7]/.test(e)) return String.fromCharCode(parseInt(e, 8));
      return ({ n: '\n', t: '\t', r: '\r', '0': '\0' })[e] ?? e;
    });
  }
  return s;
}

// minimal C preprocessor for #if/#ifdef/#ifndef/#elif/#else/#endif and #define/#undef (no macro expansion)
function preprocess(src, defines) {
  const out = [];
  const stack = [];
  const active = () => stack.every(s => s.active);
  const evalExpr = (expr) => {
    const e = expr.replace(/defined\s*\(\s*(\w+)\s*\)/g, (_, x) => (defines.has(x) ? ' 1 ' : ' 0 '))
      .replace(/defined\s+(\w+)/g, (_, x) => (defines.has(x) ? ' 1 ' : ' 0 '))
      .replace(/\b[A-Za-z_]\w*\b/g, (x) => (defines.has(x) ? (/^\d+$/.test(String(defines.get(x))) ? ' ' + defines.get(x) + ' ' : ' 1 ') : ' 0 '));
    if (!/^[\s\d()!&|<>=+\-*/%]*$/.test(e)) return false;
    try { return !!Function('"use strict";return (' + e + ');')(); } catch (_) { return false; }
  };
  for (const line of src.split('\n')) {
    const m = line.match(/^\s*#\s*(\w+)\s*(.*)$/);
    if (!m) { if (active()) out.push(line); continue; }
    const [, dir, rest] = m;
    const arg = rest.trim();
    switch (dir) {
      case 'ifdef': { const a = active(); const v = a && defines.has(arg.split(/\s/)[0]); stack.push({ active: v, taken: v, parent: a }); break; }
      case 'ifndef': { const a = active(); const v = a && !defines.has(arg.split(/\s/)[0]); stack.push({ active: v, taken: v, parent: a }); break; }
      case 'if': { const a = active(); const v = a && evalExpr(arg); stack.push({ active: v, taken: v, parent: a }); break; }
      case 'elif': { const s = stack[stack.length - 1]; if (!s) break; const v = s.parent && !s.taken && evalExpr(arg); s.active = v; s.taken = s.taken || v; break; }
      case 'else': { const s = stack[stack.length - 1]; if (!s) break; s.active = s.parent && !s.taken; s.taken = true; break; }
      case 'endif': stack.pop(); break;
      case 'define': if (active()) { const d = arg.match(/^(\w+)\s*(.*)$/); if (d) defines.set(d[1], d[2] || '1'); } break;
      case 'undef': if (active()) defines.delete(arg.split(/\s/)[0]); break;
      default: if (active()) out.push(line);  // #include, #error, #warning, #pragma: ignored
    }
  }
  return out.join('\n');
}

// PlatformIO ini: sections, multi-line values, ";" / "#" comments, ${section.key} interpolation
function parseIni(text, into) {
  const sec = into || {};
  let cur = null, key = null;
  for (const raw of text.split(/\r?\n/)) {
    if (/^\s*[;#]/.test(raw) || !raw.trim()) continue;
    const line = raw.replace(/\s[;#].*$/, '');
    const h = line.match(/^\s*\[([^\]]+)\]\s*$/);
    if (h) { cur = sec[h[1].trim()] = sec[h[1].trim()] || {}; key = null; continue; }
    if (!cur) continue;
    if (/^\s/.test(raw) && key) { cur[key] += '\n' + line.trim(); continue; }
    const kv = line.match(/^\s*([^=]+?)\s*=\s*(.*)$/);
    if (kv) { key = kv[1]; cur[key] = kv[2].trim(); }
  }
  return sec;
}

function iniResolver(sec) {
  const get = (section, key, depth = 0) => {
    if (depth > 20) return '';
    const s = sec[section];
    let v;
    if (s && key in s) v = s[key];
    else if (s && s.extends) {
      for (const base of s.extends.split(',').map(x => x.trim())) { v = get(base, key, depth + 1); if (v !== undefined) break; }
    }
    if (v === undefined && section.startsWith('env:') && sec.env && key in sec.env) v = sec.env[key];
    if (v === undefined) return undefined;
    return v.replace(/\$\{([^}]+)\}/g, (_, ref) => {
      const dot = ref.lastIndexOf('.');
      if (dot < 0 || ref.startsWith('sysenv.') || ref.startsWith('platformio.')) return '';
      return get(ref.slice(0, dot), ref.slice(dot + 1), depth + 1) || '';
    });
  };
  return get;
}

function flagsFrom(str) {
  const m = new Map();
  const re = /-D\s*([A-Za-z_]\w*)(?:=(\S+))?/g;
  let x;
  while ((x = re.exec(str || ''))) m.set(x[1], x[2] === undefined ? '1' : x[2]);
  return m;
}

