  if (!mcm) throw new Error('MODE_COUNT not found in FX.h');
  const MODE_COUNT = +mcm[1];
  B.fxIds = ids;

  const fxcpp = stripComments(rd('wled00/FX.cpp'));
  const data = new Map();
  const dataRe = /static\s+const\s+char\s+(_data_\w+)\s*\[\s*\]\s*PROGMEM\s*=\s*((?:"(?:[^"\\\n]|\\.)*"\s*)+);/g;
  for (const m of fxcpp.matchAll(dataRe)) data.set(m[1], decodeCString(m[2]));
