// util.cpp extractModeDefaults(): strstr() after the LAST ';' of the full data string, atoi() after "key="
function extractModeDefaults(fx, key) {
  if (fx >= MODE_COUNT) return -1;
  const line = BUILD.modeData[fx].slice(0, 255);
  if (!line.length) return -1;
  const sc = line.lastIndexOf(';');
  if (sc < 0) return -1;
  const p = line.indexOf(key, sc);
  if (p < 0) return -1;
  return atoi(line.slice(p + key.length + 1));
}

